style.css:
@-moz-document domain("gemini.google.com") {
:root, body, * {
    /* Paleta Divine Rose */
    --my-black: #090609;
    --my-dark: #160B15;
    --my-card: #21101F;
    --my-card-hi: #2D152A;
    --my-rose: #A9165D;
    --my-pink: #E83E91;
    --my-magenta: #FF4FA3;
    --my-text: #F5EAF1;
    --my-muted: #B9A5B3;

    /* Variables gem-sys (superficies) */
    --gem-sys-color--surface: #090609 !important;
    --gem-sys-color--surface-dim: #090609 !important;
    --gem-sys-color--surface-bright: #21101F !important;
    --gem-sys-color--surface-container-lowest: #060306 !important;
    --gem-sys-color--surface-container-low: #0E080D !important;
    --gem-sys-color--surface-container: #160B15 !important;
    --gem-sys-color--surface-container-high: #21101F !important;
    --gem-sys-color--surface-container-highest: #2D152A !important;
    --gem-sys-color--surface-variant: #3A1B35 !important;
    --gem-sys-color--on-surface: #F5EAF1 !important;
    --gem-sys-color--on-surface-variant: #B9A5B3 !important;
    --gem-sys-color--primary: #E83E91 !important;
    --gem-sys-color--on-primary: #FFFFFF !important;
    --gem-sys-color--primary-container: #5A0F35 !important;
    --gem-sys-color--on-primary-container: #FFD9EA !important;
    --gem-sys-color--secondary: #FF4FA3 !important;
    --gem-sys-color--secondary-container: #7A1148 !important;
    --gem-sys-color--on-secondary-container: #FFD9EA !important;
    --gem-sys-color--outline: #A9165D !important;
    --gem-sys-color--outline-variant: #5A2147 !important;

    /* Variables que realmente pintan el fondo en Gemini */
    --mat-app-background-color: #090609 !important;
    --mat-sidenav-container-background-color: #090609 !important;
    --mat-sidenav-content-background-color: #090609 !important;
    --mat-card-outlined-container-color: #090609 !important;
    --mat-expansion-container-background-color: #090609 !important;
    --bard-color-sidenav-background-desktop: #160B15 !important;
    --bard-color-sidenav-background-mobile: #160B15 !important;
    --bard-color-synthetic--chat-window-surface: #090609 !important;
    --bard-color-synthetic--chat-window-surface-container: #160B15 !important;
    --bard-color-synthetic--chat-window-surface-container-high: #21101F !important;
    --bard-color-synthetic--chat-window-surface-container-highest: #2D152A !important;
    --bard-color-synthetic--mat-card-background: #21101F !important;
    --bard-color-new-conversation-button: #21101F !important;
    --bard-color-footer-background: #090609 !important;
    --bard-color-response-container-flipped-background: #160B15 !important;
    --bard-color-custom-primary-container: #160B15 !important;
    --bard-color-zero-state-prompt-chip-background: #2D152A !important;
    --bard-color-zero-state-prompt-chip-text: #FFB3D6 !important;
    --bard-color-form-field-outline-active: #FF4FA3 !important;

    /* Botones, menús y diálogos de Material */
    --mat-button-filled-container-color: #E83E91 !important;
    --mat-button-filled-label-text-color: #FFFFFF !important;
    --mat-button-tonal-container-color: #5A0F35 !important;
    --mat-button-tonal-label-text-color: #FFD9EA !important;
    --mat-menu-container-color: #160B15 !important;
    --mat-dialog-container-color: #160B15 !important;
    --mat-select-panel-background-color: #160B15 !important;
    --mat-bottom-sheet-container-background-color: #160B15 !important;
    --mat-progress-bar-active-indicator-color: #E83E91 !important;
    --mat-progress-spinner-active-indicator-color: #E83E91 !important;
    --mat-form-field-outlined-focus-outline-color: #FF4FA3 !important;
    --mat-tab-active-indicator-color: #E83E91 !important;
    --mat-list-active-indicator-color: #5A0F35 !important;
    --mat-chip-selected-label-text-color: #FFD9EA !important;
    --mat-option-selected-state-layer-color: #5A0F35 !important;
    --mat-slide-toggle-selected-track-color: #E83E91 !important;
  }

  html, body {
    background-color: #090609 !important;
    color-scheme: dark !important;
  }

  a { color: var(--my-magenta) !important; }

  ::selection {
    background: var(--my-rose) !important;
    color: #fff !important;
  }

  /* Resplandor sutil en botones */
  button:hover {
    box-shadow: 0 0 10px rgba(232, 62, 145, 0.55) !important;
  }
}
